/// Frozen legacy contract - the old client decodes exactly this shape.
struct LegacyQuote: Codable {
    let SKU: String                 // name from the legacy format, not Swift style
    let unit_price: String          // decimal as text
    let ccy: String?
    enum CodingKeys: String, CodingKey { case SKU, unit_price, ccy }
}
@available(*, deprecated, message: "legacy window: dies with client X")
func legacyQuoteJSON(_ q: Quote) throws -> Data {          // window entry point
    let wire = LegacyQuote(SKU: q.sku, unit_price: decimalString(q.cents), ccy: q.currency)
    return try JSONEncoder().encode(wire)                  // old keys, old text decimals
}
